<script setup lang="ts">
import BacktestPanel from './BacktestPanel.vue'
import TemplateTools from './TemplateTools.vue'
import {downloadCsv} from '../../utils/export'
import {allOptions} from '../../api/options'
import{computed,reactive,ref,watch}from'vue';import{useRoute}from'vue-router';import{http}from'../../api/http';import{useAuthStore}from'../../stores/auth';import{day}from'../../utils/dates';import TrendChart from'../../components/TrendChart.vue';import type {Row} from '../../shared/records'
const auth=useAuthStore(),route=useRoute(),date=ref(day(1)),meal=ref('LUNCH'),menu=ref<Row>({items:[]}),allergens=ref<Row[]>([]),dishes=ref<Row[]>([]),chosen=ref<number>(),error=ref(''),pending=ref(false),warning=ref(''),success=ref(''),forecast=ref<Row>({points:[],history:[]}),preparation=ref<Row>({items:[]})
function exportPreparation(){downloadCsv('备餐出餐清单',['菜品','已确认份数','预测人数','建议份数','人工调整'],preparation.value.items.map((r:Row)=>[r.dishName,r.confirmedQty,r.forecastCount,r.suggestedQty,r.adjustedQty]))}
function applyDestination(d:string,m:string){date.value=d;meal.value=m;void load()}
function printList(){window.print()}
const community=computed(()=>route.path.startsWith('/community')),mode=computed(()=>route.path.endsWith('/forecasts')?'forecast':route.path.endsWith('/preparation')?'preparation':'menu'),site=computed(()=>auth.currentSiteId),nutritionFields=[['caloriesKcal','能量 kcal'],['proteinGrams','蛋白质 g'],['fatGrams','脂肪 g'],['carbGrams','碳水 g'],['sodiumMg','钠 mg']]
let generation=0
async function load(){if(!site.value)return;const request=++generation;pending.value=true;error.value='';warning.value='';forecast.value={points:[],history:[]};preparation.value={items:[]};try{const loadedMenu=await http.get<never,Row>(`/sites/${site.value}/menus`,{params:{date:date.value,mealType:meal.value}});if(request!==generation)return;menu.value={...loadedMenu,items:(loadedMenu.items??[]).map((item:Row)=>({...item,nutritionOverride:{...(item.nutrition??{}),...(item.nutritionOverride??{})}}))};allergens.value=await http.get('/allergens');if(!community.value){const siteId=site.value,selectedDate=date.value,selectedMeal=meal.value;await Promise.all([http.get<never,Row>(`/sites/${siteId}/forecasts`,{params:{startDate:selectedDate,days:7,mealType:selectedMeal}}).then(data=>{if(request===generation)forecast.value=data}).catch(e=>{if(request===generation)warning.value=`预测暂不可用：${e.message}。可继续按已确认订单安排备餐。`}),allOptions('/dishes?size=100').then(data=>{if(request===generation)dishes.value=data}),...(mode.value==='preparation'?[http.get<never,Row>(`/sites/${siteId}/preparation-list`,{params:{date:selectedDate,mealType:selectedMeal}}).then(data=>{if(request===generation)preparation.value=data})]:[])])}}catch(e){if(request===generation)error.value=(e as Error).message}finally{if(request===generation)pending.value=false}}

async function add(){const selected=dishes.value.find(d=>d.id===chosen.value);if(!selected){error.value='请先选择菜品';return}if(menu.value.items.some((v:Row)=>v.dishId===selected.id)){error.value='该菜品已在菜谱中';return}const dish=await http.get<never,Row>(`/dishes/${selected.id}`);menu.value.items.push({dishId:dish.id,dishName:dish.name,ingredients:dish.ingredients,allergenIds:dish.allergenIds??[],allergenDataComplete:dish.allergenDataComplete,plannedQty:0,servingWeightGrams:dish.weightGrams??'',nutritionOverride:Object.fromEntries(nutritionFields.map(([key])=>[key!,dish[key!]??''])),availability:'AVAILABLE'})}
async function action(name:string,item?:Row){if(pending.value)return;pending.value=true;error.value='';try{if(name==='save'){const body={serviceDate:date.value,mealType:meal.value,items:menu.value.items.map((v:Row)=>({dishId:v.dishId,plannedQty:v.plannedQty,allergenIds:v.allergenIds??[],ingredients:Array.isArray(v.ingredients)?v.ingredients:String(v.ingredients??'').split(/[,，]/).map(s=>s.trim()).filter(Boolean),allergenDataComplete:!!v.allergenDataComplete, ...(v.servingWeightGrams?{servingWeightGrams:v.servingWeightGrams}:{}),nutritionOverride:Object.fromEntries(Object.entries(v.nutritionOverride??{}).filter(([,v])=>v!==''&&v!==null))}))};if(menu.value.id)await http.put(`/sites/${site.value}/menus/${menu.value.id}`,body);else await http.post(`/sites/${site.value}/menus`,body)}else if(name==='availability')await http.patch(`/sites/${site.value}/menu-items/${item!.id}/availability`,{availability:item!.availability==='AVAILABLE'?'OFF_SHELF':'AVAILABLE'});else if(name==='adjust')await http.put(`/sites/${site.value}/preparation-list`,{items:preparation.value.items.filter((v:Row)=>v.adjustedQty!==null&&v.adjustedQty!=='').map((v:Row)=>({menuItemId:v.menuItemId,adjustedQty:v.adjustedQty}))},{params:{date:date.value,mealType:meal.value}});else await http.post(`/sites/${site.value}/menus/${menu.value.id}/${name}`);success.value=({save:'草稿已保存',submit:'菜谱已上报',publish:'菜谱已发布',adjust:'备餐计划已保存',availability:'可售状态已更新'} as Row)[name]??'操作成功';await load()}catch(e){error.value=(e as Error).message}finally{pending.value=false}}
watch(()=>[site.value,date.value,meal.value,route.path],()=>void load(),{immediate:true})
</script>
<template><section><p class="eyebrow">餐食服务</p><h1>{{mode==='forecast'?'就餐人数预测':mode==='preparation'?'备餐出餐清单':community?'每日菜谱确认':'菜谱上报'}}</h1><div class="toolbar"><label for="meal-date">供餐日期</label><el-input id="meal-date" v-model="date" type="date"/><el-select v-model="meal" aria-label="餐次"><el-option label="午餐" value="LUNCH"/><el-option label="晚餐" value="DINNER"/></el-select><el-button @click="load">刷新</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/>
<el-alert v-if="warning" :title="warning" type="warning" :closable="false"/><el-alert v-if="success" :title="success" type="success" :closable="false"/><template v-if="mode==='menu'"><TemplateTools v-if="!community" :site="site??undefined" :menu-id="menu.id" :date="date" :meal="meal" @applied="applyDestination"/><p>当前状态：{{({DRAFT:'草稿',SUBMITTED:'待社区确认',PUBLISHED:'已发布'} as Row)[menu.status]??'尚未创建'}}</p><div v-if="!community" class="toolbar"><el-select v-model="chosen" filterable aria-label="选择菜品"><el-option v-for="dish in dishes.filter(d=>d.status==='ACTIVE')" :key="dish.id" :value="dish.id" :label="dish.name"/></el-select><el-button @click="add">添加菜品</el-button><el-button type="primary" :loading="pending" @click="action('save')">保存草稿</el-button><el-button v-if="menu.status==='DRAFT'" :loading="pending" @click="action('submit')">上报菜谱</el-button></div><el-button v-if="community&&menu.status==='SUBMITTED'" type="primary" :loading="pending" @click="action('publish')">确认发布</el-button>
<el-table :data="menu.items" empty-text="暂无菜谱"><el-table-column prop="dishName" label="菜品" min-width="140"/><el-table-column label="可售份数" min-width="110"><template #default="{row}"><el-input v-if="!community" v-model="row.plannedQty" type="number" min="0" aria-label="可售份数"/><span v-else>{{row.plannedQty}}</span></template></el-table-column><el-table-column label="每份克重 g" min-width="120"><template #default="{row}"><el-input v-if="!community" v-model="row.servingWeightGrams" type="number" step="any" aria-label="每份克重"/><span v-else>{{row.servingWeightGrams??row.weightGrams}}</span></template></el-table-column><el-table-column label="食材与过敏原核对" min-width="180"><template #default="{row}"><template v-if="!community"><el-select v-model="row.allergenIds" multiple aria-label="餐品过敏原"><el-option v-for="allergen in allergens" :key="allergen.id" :value="allergen.id" :label="allergen.name"/></el-select><el-input :model-value="Array.isArray(row.ingredients)?row.ingredients.join('，'):row.ingredients" aria-label="餐品主要食材" @update:model-value="(value:string)=>row.ingredients=value"/></template><p v-else>{{(row.ingredients??[]).join('、')}} · {{allergens.filter(a=>(row.allergenIds??[]).includes(a.id)).map(a=>a.name).join('、')}}</p><el-checkbox v-if="!community" v-model="row.allergenDataComplete">资料已完整核对</el-checkbox><span v-else>{{row.allergenDataComplete?'资料完整':'待核对'}}</span></template></el-table-column><el-table-column v-for="[key,label] in nutritionFields" :key="key" :label="label" min-width="120"><template #default="{row}"><el-input v-if="!community" v-model="row.nutritionOverride[key!]" type="number" step="any" :aria-label="label"/><span v-else>{{row.nutritionOverride[key!]??'未登记'}}</span></template></el-table-column><el-table-column label="状态与操作" min-width="180"><template #default="{row}">{{row.availability==='AVAILABLE'?'可售':'已下架'}}<el-button v-if="community" link @click="action('availability',row)">{{row.availability==='AVAILABLE'?'临时下架':'恢复可售'}}</el-button><el-button v-else link type="danger" @click="menu.items.splice(menu.items.indexOf(row),1)">移除</el-button></template></el-table-column></el-table></template>
<template v-if="mode==='preparation'"><el-alert v-if="preparation.warning" :title="preparation.warning" type="info" :closable="false"/><el-table :data="preparation.items"><el-table-column prop="dishName" label="菜品"/><el-table-column prop="confirmedQty" label="已确认份数"/><el-table-column prop="forecastCount" label="预测人数"/><el-table-column prop="suggestedQty" label="参考份数"/><el-table-column label="人工备餐份数"><template #default="{row}"><el-input v-model="row.adjustedQty" type="number" min="0"/></template></el-table-column></el-table><div class="toolbar"><el-button type="primary" @click="action('adjust')">保存备餐计划</el-button><el-button @click="printList()">打印备餐单</el-button><el-button @click="exportPreparation">导出备餐 CSV</el-button></div></template>
<section v-if="!community" class="content-card" style="margin-top:24px"><h2>未来七天就餐人数</h2><p>算法：{{forecast.algorithm||'尚未加载'}}</p><TrendChart :labels="forecast.points.map((v:Row)=>v.date)" :series="[{name:'预测人数',data:forecast.points.map((v:Row)=>v.count)}]"/><el-table :data="forecast.points"><el-table-column prop="date" label="日期"/><el-table-column label="预测人数"><template #default="{row}">{{row.closed?'不营业':row.insufficientData?'历史数据不足':row.count}}</template></el-table-column><el-table-column prop="sampleCount" label="历史样本数"/><el-table-column label="使用的历史日期" min-width="240"><template #default="{row}">{{(row.sampleDates??[]).join('、')||'无可用样本'}}</template></el-table-column></el-table><h3>历史实际人数</h3><TrendChart :labels="[...forecast.history].reverse().map((v:Row)=>v.date)" :series="[{name:'实际人数',data:[...forecast.history].reverse().map((v:Row)=>v.count)}]"/></section><BacktestPanel v-if="mode==='forecast'&&!community" :site="site??undefined" :meal="meal"/>
</section></template>
